export function getSistemEkonomiBySlug(slug?: string | null): SistemEkonomiCountryData | null {
  if (!slug) return null;
  const clean = slug.toLowerCase().trim();
  const s1 = clean.replace(/_/g, '-');
  const s2 = clean.replace(/-/g, '_');
  return DATABASE_SISTEM_EKONOMI[clean] || DATABASE_SISTEM_EKONOMI[s1] || DATABASE_SISTEM_EKONOMI[s2] || null;
}

export default DATABASE_SISTEM_EKONOMI;
